# Set default values for the ENV_VFOLD_* environment variables read at runtime
# by the vfold code of this process directory (generated by 'output --vfold'),
# and print them. Source this file before running the process directory, e.g.
#   source vfold/setupVfoldDefaults.sh
#   ./bin/generate_events
# Variables that are already set are kept as they are.
#
# NB! These are only EXAMPLES of reasonable values: users must tune them to
# their own needs (e.g. ENV_VFOLD_CUDACPP_BACKEND to the SIMD instruction set
# of their CPU, or cuda on a GPU) and to their machine.

if [ "${BASH_SOURCE[0]}" == "$0" ]; then
  echo "ERROR! This script must be sourced: source $0"
  exit 1
fi

# The process directory (this file is <procdir>/vfold/setupVfoldDefaults.sh)
vfold_procdir=$(cd $(dirname ${BASH_SOURCE[0]})/..; pwd -P)

# Mode C: Born and Real matrix elements from the cudacpp libraries
# (built in <procdir>/lib/cudacpp by 'output --vfold')
export ENV_VFOLD_ME_MODE=${ENV_VFOLD_ME_MODE:-C}
export ENV_VFOLD_CUDACPP_BASE=${ENV_VFOLD_CUDACPP_BASE:-${vfold_procdir}/lib/cudacpp}
# The cudacpp backend: none, sse4, avx2, 512y, 512z (SIMD on CPU) or cuda (GPU)
export ENV_VFOLD_CUDACPP_BACKEND=${ENV_VFOLD_CUDACPP_BACKEND:-avx2}
# SBORN served from the Born points evaluated by cudacpp (road B steps 9i+9j)
export ENV_VFOLD_SBORN_BRIDGE=${ENV_VFOLD_SBORN_BRIDGE:-1}
# SBORN at another coupling g served by rescaling (road B step 10b)
export ENV_VFOLD_SBORN_GSCALE=${ENV_VFOLD_SBORN_GSCALE:-1}
unset vfold_procdir

echo "MadVFold: ENV_VFOLD_* variables (these are only examples: tune them to your needs)"
echo "ENV_VFOLD_ME_MODE=${ENV_VFOLD_ME_MODE}"
echo "ENV_VFOLD_CUDACPP_BASE=${ENV_VFOLD_CUDACPP_BASE}"
echo "ENV_VFOLD_CUDACPP_BACKEND=${ENV_VFOLD_CUDACPP_BACKEND}"
echo "ENV_VFOLD_SBORN_BRIDGE=${ENV_VFOLD_SBORN_BRIDGE}"
echo "ENV_VFOLD_SBORN_GSCALE=${ENV_VFOLD_SBORN_GSCALE}"
